<?php
declare(strict_types=1);
namespace WexaShelf;
final class Admission {
 public static function defaults(): array { return ['revision'=>0,'country'=>'TR','profiles'=>array_fill_keys(['android','ios','windows'],['enabled'=>false,'minimum'=>0])]; }
 public static function validate(mixed $r): array { Validation::check(is_array($r)&&is_int($r['revision']??null)&&$r['revision']>=0&&$r['revision']<=9007199254740991&&Validation::country(strtoupper($r['country']??'')),'Geçersiz kural revizyonu veya ülke.'); $profiles=[]; foreach(['android','ios','windows'] as $p) { $v=$r['profiles'][$p]??null; Validation::check(is_array($v)&&is_bool($v['enabled']??null)&&is_int($v['minimum']??null)&&$v['minimum']>=0&&$v['minimum']<=9007199254740991,'Eşik sıfır veya pozitif tam sayı olmalı.'); $profiles[$p]=['enabled'=>$v['enabled'],'minimum'=>$v['minimum']]; } return ['revision'=>$r['revision'],'country'=>strtoupper($r['country']),'profiles'=>$profiles]; }
 public static function officialSource(string $p,string $url): bool { $u=parse_url($url); return is_array($u)&&($u['scheme']??'')==='https'&&!isset($u['user'],$u['pass'])&&!isset($u['user'])&&!isset($u['pass'])&&in_array(strtolower($u['host']??''),['android'=>['play.google.com'],'ios'=>['apps.apple.com','itunes.apple.com'],'windows'=>['apps.microsoft.com','www.microsoft.com']][$p]??[],true); }
 public static function evaluate(array $app,array $rules,string $exception=''): array { $enabled=array_keys(array_filter($rules['profiles'],fn($v)=>$v['enabled'])); if(!$enabled)return ['accepted'=>true,'state'=>'not-configured','reasons'=>['Mağaza kabul eşikleri henüz yapılandırılmadı.']]; $reasons=[]; foreach($enabled as $p) { $label=$p==='android'?'Android indirme alt sınırı':($p==='ios'?'iOS':'Windows').' değerlendirme sayısı'; if(!in_array($p,$app['platforms'],true)){ $reasons[]="$label: bu platformda kayıt yok.";continue;} $observations=array_values(array_filter($app['storeMetrics'],fn($m)=>$m['platform']===$p&&strtoupper($m['country'])===$rules['country']&&strtotime($m['observedAt'])!==false)); usort($observations,fn($a,$b)=>strtotime($b['observedAt'])<=>strtotime($a['observedAt']));$m=$observations[0]??null;$value=$m[$p==='android'?'downloadsLowerBound':'ratingCount']??null; if(!$m||!self::officialSource($p,$m['sourceUrl'])||!is_int($value)||$value<0){$reasons[]="$label: bu ülke için kaynaklı güncel gözlem yok.";continue;} $minimum=$rules['profiles'][$p]['minimum'];if($value>=$minimum)return ['accepted'=>true,'state'=>'passed','reasons'=>["$label $value; {$rules['country']} eşiği $minimum karşılandı."]];$reasons[]="$label $value; gerekli eşik $minimum."; } if(strlen(trim($exception))>=20)return ['accepted'=>true,'state'=>'exception','reasons'=>[...$reasons,'Editoryal istisna: '.trim($exception)]];return ['accepted'=>false,'state'=>'rejected','reasons'=>$reasons]; }
}
